package hu.synostream.android;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;
public class AppReleaseTest {
 final byte[] bytes={1,2,3,4};
 JSONObject json()throws Exception{return new JSONObject().put("format",1).put("platform","android").put("application_id","hu.synostream.android").put("version","0.5.20").put("version_code",25).put("min_sdk",26).put("filename","SynoStream_Android_0.5.20.apk").put("url","https://github.com/x10ilaci/SynoStream/releases/download/android-v0.5.20/SynoStream_Android_0.5.20.apk").put("size",4).put("sha256",AppRelease.digest(bytes)).put("signing_certificate_sha256","a".repeat(64)).put("notes","Fixture");}
 HttpURLConnection connection(byte[] body)throws Exception{return new HttpURLConnection(new URL(AppRelease.FEED)){public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public InputStream getInputStream(){return new ByteArrayInputStream(body);}};}
 @Test public void monotonicVersionAndCompatibility()throws Exception{AppRelease r=new AppRelease(json());assertTrue(r.newer(24,26));assertFalse(r.newer(25,36));assertFalse(r.newer(26,36));assertFalse(r.newer(24,25));}
 @Test public void wrongIdentityRejected()throws Exception{for(String field:List.of("format","platform","application_id","version","version_code","size","sha256","signing_certificate_sha256","url","filename","min_sdk")){JSONObject j=json();j.put(field,field.equals("size")?-1:field.equals("version_code")?0:field.equals("min_sdk")?1:"invalid");assertThrows(field,Exception.class,()->new AppRelease(j));}}
 @Test public void oversizedAndMissingFieldsRejected()throws Exception{assertThrows(Exception.class,()->new AppRelease(json().put("size",AppRelease.MAX_APK+1)));JSONObject j=json();j.remove("sha256");assertThrows(Exception.class,()->new AppRelease(j));}
 @Test public void urlsRequireHttpsAndExactGithubHost()throws Exception{for(String u:List.of("http://github.com/a","https://evil.com/a","https://github.com.evil.com/a","https://user@github.com/a","https://github.com:444/a"))assertFalse(u,AppRelease.allowed(new URL(u)));assertTrue(AppRelease.allowed(new URL("https://release-assets.githubusercontent.com/a")));assertThrows(Exception.class,()->new AppRelease(json().put("url","https://github.com/other/repo/releases/download/x/a.apk")));}
 @Test public void fetchIsBoundedAndParsesMetadata()throws Exception{AppRelease r=AppRelease.fetch(u->connection(json().toString().getBytes("UTF-8")));assertEquals(25,r.code);assertThrows(IOException.class,()->AppRelease.fetch(u->connection(new byte[65537])));assertThrows(Exception.class,()->AppRelease.fetch(u->connection("bad".getBytes())));}
 @Test public void downloadVerifiedAndAtomicallyFinalized()throws Exception{File dir=Files.createTempDirectory("update-test").toFile(),apk=new File(dir,"update.apk");try{List<Long> progress=new ArrayList<>();new AppRelease(json()).download(apk,(n,total)->progress.add(n),u->connection(bytes));assertArrayEquals(bytes,Files.readAllBytes(apk.toPath()));assertEquals(List.of(4L),progress);assertFalse(new File(dir,"download.part").exists());}finally{apk.delete();dir.delete();}}
 @Test public void corruptTruncatedAndOversizedDownloadsNeverReplaceGoodFile()throws Exception{File dir=Files.createTempDirectory("update-test").toFile(),apk=new File(dir,"update.apk");try{Files.write(apk.toPath(),new byte[]{9});for(byte[] bad:List.of(new byte[]{1},new byte[]{4,3,2,1},new byte[]{1,2,3,4,5})){assertThrows(Exception.class,()->new AppRelease(json()).download(apk,(n,total)->{},u->connection(bad)));assertArrayEquals(new byte[]{9},Files.readAllBytes(apk.toPath()));assertFalse(new File(dir,"download.part").exists());}}finally{apk.delete();dir.delete();}}
 @Test public void failedConnectionLeavesNoPartialFile()throws Exception{File dir=Files.createTempDirectory("update-test").toFile(),apk=new File(dir,"update.apk");try{assertThrows(IOException.class,()->new AppRelease(json()).download(apk,(n,total)->{},u->{throw new IOException("fixture timeout");}));assertFalse(apk.exists());assertFalse(new File(dir,"download.part").exists());}finally{dir.delete();}}
}
